// Calculate the velocity component along the cube's up axis
Vector3 upComponent = dotProduct * objectVelocity.magnitude * cubeUp;

// Subtract the up component from the original velocity
Vector3 newVelocity = objectVelocity - upComponent;

// Assign the new velocity back to the sphere
sphere.rigidbody.velocity = newVelocity;
